package com.utegear.entity;
import static org.assertj.core.api.Assertions.*; import java.math.BigDecimal; import java.util.Map; import org.junit.jupiter.api.Test;
class ProductTest { private Category category(){return new Category("Bàn phím","ban-phim",null,0);} @Test void rejectsSalePriceAboveBase(){assertThatThrownBy(()->new Product("K87","k87",category(),null,new BigDecimal("100"),new BigDecimal("101"))).isInstanceOf(IllegalArgumentException.class);} @Test void rejectsProductWithoutVariant(){Product p=new Product("K87","k87",category(),null,new BigDecimal("100"),null);assertThatThrownBy(p::create).isInstanceOf(IllegalStateException.class);} @Test void acceptsExactlyOneDefaultVariant(){Product p=new Product("K87","k87",category(),null,new BigDecimal("100"),null);p.addVariant(new ProductVariant("K87-DEFAULT",Map.of(),true,BigDecimal.ZERO));assertThatCode(p::create).doesNotThrowAnyException();} @Test void rejectsMultipleDefaultVariants(){Product p=new Product("K87","k87",category(),null,new BigDecimal("100"),null);p.addVariant(new ProductVariant("K87-A",Map.of("color","black"),true,BigDecimal.ZERO));p.addVariant(new ProductVariant("K87-B",Map.of("color","white"),true,BigDecimal.ZERO));assertThatThrownBy(p::create).isInstanceOf(IllegalStateException.class);} }
